function voyCopyShip(ob, sh, faction) { const used = new Set(voyObShips(ob).map(x => x.name)), x = JSON.parse(JSON.stringify(sh));x.id = voyUid(ob);x.name = voyNextName(faction, used);delete x.customName;return x; }
