 if (xs.some(x => x.st === 'beam')) return ' · 超兵器 照射中';if (xs.some(x => x.st === 'ready')) return ' · 超兵器 発射可';
 const c = Math.max(...xs.map(x => x.st === 'charge' ? x.c || 0 : 0));if (xs.some(x => x.st === 'charge')) return ` · 超兵器 充電 ${Math.round(c * 100)}%`;
