   for (const [sel, hint] of [[`[data-vrec="${u.id}"]:not([disabled])`, '「後方へ回収」を押す'], [`[data-vtrq="tow:${u.id}"]`, '「牽引で回収」を押す'], [`[data-vscuttle="${u.id}"]`, '「自沈」を押す（確定にもう一度）']]) { const e = voy.side && vtutQ('#voySide ' + sel); if (e) return {el: e, hint}; }
