  if (MS?.active) { msLog(MS, MS.active.kind === 'battle' ? '前回の艦隊戦は中断されました（出撃した艦は損傷なしで戦域に残っています）' : '前回のパトロールは中断されました（任務群は出発した星系にいます）'); MS.active = null; }
