function msFactionOptions(cur) { return Object.keys(MS_HOME).map(f => `<option value="${f}" ${f === cur ? 'selected' : ''}>${esc(R.FACTIONS[f].name)}（${msEraName(msEraOf(f))}・母港 ${esc(msSysName(MS_HOME[f]))}）</option>`).join(''); }
