 const all = voyObTgs(st.ob).filter(t => msReadyShips(t).length), tgs = msSortieTgs(st), ships = tgs.flatMap(msReadyShips), eta = msSortieEta(st, tgs, f.sys), info = msFoeInfo(f), a = voyShipsStrength(ships), r = a > 0 ? info.str / a : 0;
